import csv,random,statistics as S,collections as C
from datetime import datetime as D
random.seed(1)
p=lambda s:D.strptime(s,'%Y-%m-%dT%H:%M:%SZ')
EX=p('2026-06-22T23:59:00Z')
I=list(csv.DictReader(open('incidents.csv')));A={r['incident_id']:r for r in csv.DictReader(open('activity.csv'))}
rows=[]
for r in I:
    a=A.get(r['incident_id']);o=p(r['opened_at'])
    r['post']=r['workflow']=='assist'
    r['ttc']=(p(a['closed_at'])-o).total_seconds()/3600 if a else None
    r['cens']=(EX-o).total_seconds()/3600
    if a: r['rm']=int(a['responder_minutes']);r['ho']=int(a['handoffs']);r['re']=int(a['reopened_within_72h'])
    rows.append(r)
def med(x):return S.median(x) if x else float('nan')
def boot(f,g1,g2,n=2000):
    d=[]
    for _ in range(n):
        a=[random.choice(g1) for _ in g1];b=[random.choice(g2) for _ in g2]
        d.append(f(b)-f(a))
    d.sort();return d[int(.025*n)],d[int(.975*n)]
def rep(name,sel,key):
    pre=[r[key] for r in rows if sel(r) and not r['post'] and r.get(key) is not None]
    po=[r[key] for r in rows if sel(r) and r['post'] and r.get(key) is not None]
    lo,hi=boot(med,pre,po)
    print(f"{name:28s} {key} pre n={len(pre)} med={med(pre):.2f} | post n={len(po)} med={med(po):.2f} | diff={med(po)-med(pre):+.2f} CI[{lo:+.2f},{hi:+.2f}]")
for k in ['ttc','rm']:
    rep('ALL',lambda r:True,k)
    for s in ['sev1','sev2','sev3']: rep(s,lambda r,s=s:r['severity']==s,k)
    for g in ['identity','storage']: rep(g,lambda r,g=g:r['service_group']==g,k)
print('--mix')
for per in [False,True]:
    s=[r for r in rows if r['post']==per];print('post' if per else 'pre',len(s),{k:round(v/len(s),3) for k,v in sorted(C.Counter(r['severity'] for r in s).items())},{k:round(v/len(s),3) for k,v in sorted(C.Counter(r['intake_channel'] for r in s).items())})
print('--missing',C.Counter((r['post'],r['severity'],r['ttc'] is None) for r in rows if r['ttc'] is None or True and False))
for per in [False,True]:
    for sv in ['sev1','sev2','sev3']:
        s=[r for r in rows if r['post']==per and r['severity']==sv];print(per,sv,len(s),sum(r['ttc'] is None for r in s))
print('--handoffs/reopens')
for per in [False,True]:
    for sv in ['sev1','sev2','sev3']:
        s=[r for r in rows if r['post']==per and r['severity']==sv and r['ttc'] is not None]
        print(per,sv,'handoffs mean',round(S.mean(r['ho'] for r in s),2),'reopen',round(S.mean(r['re'] for r in s),3),'rm mean',round(S.mean(r['rm'] for r in s),1),'ttc mean',round(S.mean(r['ttc'] for r in s),2))
# bounding: missing assigned censored value (cens hours) -> median
for lab,fill in [('missing=censored at extract (lower bound)',True)]:
    pre=[r['ttc'] if r['ttc'] is not None else r['cens'] for r in rows if not r['post']]
    po=[r['ttc'] if r['ttc'] is not None else r['cens'] for r in rows if r['post']]
    print(lab,'pre',med(pre),'post',med(po),med(po)-med(pre))
# best case: missing excluded; and missing as slowest
# daily medians
d=C.defaultdict(list)
for r in rows:
    if r['ttc'] is not None:d[r['opened_at'][:10]].append(r['ttc'])
print({k:round(med(v),1) for k,v in sorted(d.items())})
# TTC by day within sev3 and per group-day staffing? tot responder hours
tot=lambda per:sum(r['rm'] for r in rows if r['post']==per and r.get('rm') is not None)/60
print('total responder hours pre',tot(False),'post',tot(True))
E

